import { randomUUID } from "node:crypto";

import { expect, expectStatus, test } from "../../fixtures";

interface VendorBody {
  id: string;
  status: string;
}

interface DocumentBody {
  id: string;
  vendor_id: string;
  kind: string;
  status: string;
}

interface FieldBody {
  value: string | null;
  confidence: number;
}

interface ExtractionBody {
  document_id: string;
  kind: string;
  fields: Record<string, FieldBody>;
}

test.describe("Upload vendor documents", () => {
  test(
    "Fields that cannot be parsed get low confidence",
    { tag: "@DOC-03" },
    async ({ apiAs }) => {
      // Arrange: a member signed in, with a vendor in status "draft"
      const member = await apiAs("member");
      const suffix = randomUUID();

      const vendorResponse = await member.post("/api/vendors", {
        data: {
          name: `Intake Vendor ${suffix}`,
          category: "services",
          contact_email: `ops+${suffix}@example.test`,
        },
      });
      const vendor = await expectStatus<VendorBody>(vendorResponse, 201);
      expect(vendor.status).toBe("draft");

      // Arrange: an insurance certificate whose expiry date is "next spring"
      const certificateText = `Certificate of Insurance\nExpiry date: next spring\n`;

      // Act: upload the insurance certificate
      const uploadResponse = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "insurance_certificate",
          file: {
            name: `insurance-${suffix}.pdf`,
            mimeType: "application/pdf",
            buffer: Buffer.from(certificateText, "utf-8"),
          },
        },
      });
      const document = await expectStatus<DocumentBody>(uploadResponse, 201);
      expect(document.vendor_id).toBe(vendor.id);
      expect(document.kind).toBe("insurance_certificate");

      // Act: wait for background processing to finish
      await expect
        .poll(
          async () => {
            const response = await member.get(`/api/documents/${document.id}`);
            return (await expectStatus<DocumentBody>(response, 200)).status;
          },
          { timeout: 60_000, intervals: [500, 1000, 2000] },
        )
        .not.toBe("processing");

      const finished = await expectStatus<DocumentBody>(
        await member.get(`/api/documents/${document.id}`),
        200,
      );
      expect(finished.status).toBe("extracted");

      // Assert: the expiry_date field has a null value and confidence below 0.5
      const extractionResponse = await member.get(`/api/documents/${document.id}/extraction`);
      const extraction = await expectStatus<ExtractionBody>(extractionResponse, 200);
      expect(extraction.document_id).toBe(document.id);

      const expiry = extraction.fields["expiry_date"];
      expect(expiry).toBeDefined();
      expect(expiry.value).toBeNull();
      expect(expiry.confidence).toBeLessThan(0.5);
    },
  );
});
